def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = 8

    # Choose the diagonal orientation containing the longer input strokes.
    down_right = 0
    down_left = 0
    for r in range(h - 1):
        for c in range(w):
            value = grid[r][c]
            if value == bg:
                continue
            if c + 1 < w and grid[r + 1][c + 1] == value:
                down_right += 1
            if c > 0 and grid[r + 1][c - 1] == value:
                down_left += 1

    use_sum = down_left > down_right

    # Group cells by diagonal, then split each diagonal into contiguous segments.
    groups = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                p, q = (r + c, c - r) if use_sum else (c - r, r + c)
                groups.setdefault(p, []).append(q)

    segments = []
    for p, values in groups.items():
        values = sorted(set(values))
        start = prev = values[0]
        for q in values[1:] + [None]:
            if q is None or q != prev + 2:
                segments.append((p, start, prev))
                if q is None:
                    break
                start = q
            prev = q

    out = [row[:] for row in grid]
    for i, (p1, a1, b1) in enumerate(segments):
        for p2, a2, b2 in segments[i + 1:]:
            if p1 == p2:
                continue
            q0, q1 = max(a1, a2), min(b1, b2)
            if q0 > q1:
                continue
            lo, hi = sorted((p1, p2))
            for r in range(h):
                for c in range(w):
                    if grid[r][c] != bg:
                        continue
                    p, q = (r + c, c - r) if use_sum else (c - r, r + c)
                    if lo < p < hi and q0 <= q <= q1:
                        out[r][c] = 2
    return out
